aggregateGroupByKey(RequestResource, Htt.code:
{
    final long startTime = System.currentTimeMillis();
    MapReducer<OSMEntitySnapshot> mapRed = null;
    InputProcessor inputProcessor = new InputProcessor(servletRequest, isSnapshot, isDensity);
    String[] groupByKeys = inputProcessor.splitParamOnComma(inputProcessor.createEmptyArrayIfNull(servletRequest.getParameterValues("groupByKeys")));
    if (groupByKeys == null || groupByKeys.length == 0) {
        throw new BadRequestException(ExceptionMessages.GROUP_BY_KEYS_PARAM);
    }
    mapRed = inputProcessor.processParameters();
    ProcessingData processingData = inputProcessor.getProcessingData();
    RequestParameters requestParameters = processingData.getRequestParameters();
    TagTranslator tt = DbConnData.tagTranslator;
    Integer[] keysInt = new Integer[groupByKeys.length];
    for (int i = 0; i < groupByKeys.length; i++) {
        keysInt[i] = tt.getOSHDBTagKeyOf(groupByKeys[i]).map(OSHDBTagKey::toInt).orElse(-i - 2);
    }
    MapAggregator<OSHDBCombinedIndex<OSHDBTimestamp, Integer>, OSMEntitySnapshot> preResult = mapRed.flatMap(f -> {
        List<Pair<Integer, OSMEntitySnapshot>> res = new LinkedList<>();
        Iterable<OSHDBTag> tags = f.getEntity().getTags();
        for (OSHDBTag tag : tags) {
            int tagKeyId = tag.getKey();
            for (int key : keysInt) {
                if (tagKeyId == key) {
                    res.add(new ImmutablePair<>(tagKeyId, f));
                }
            }
        }
        if (res.isEmpty()) {
            res.add(new ImmutablePair<>(-1, f));
        }
        return res;
    }).aggregateByTimestamp().aggregateBy(Pair::getKey, Arrays.asList(keysInt)).map(Pair::getValue);
    var result = ExecutionUtils.computeResult(requestResource, preResult);
    var groupByResult = ExecutionUtils.nest(result);
    GroupByResult[] resultSet = new GroupByResult[groupByResult.size()];
    String groupByName = "";
    int count = 0;
    for (var entry : groupByResult.entrySet()) {
        ElementsResult[] results = ExecutionUtils.fillElementsResult(entry.getValue(), requestParameters.isDensity(), df, null);
        // check for non-remainder objects (which do have the defined key)
        if (entry.getKey() == -1) {
            groupByName = "remainder";
        } else if (entry.getKey() < -1) {
            groupByName = groupByKeys[-entry.getKey() - 2];
        } else {
            groupByName = tt.lookupTag(entry.getKey(), 0).getKey();
        }
        resultSet[count] = new GroupByResult(groupByName, results);
        count++;
    }
    Metadata metadata = null;
    if (processingData.isShowMetadata()) {
        long duration = System.currentTimeMillis() - startTime;
        metadata = new Metadata(duration, Description.aggregateGroupByKey(requestResource.getDescription(), requestResource.getUnit()), inputProcessor.getRequestUrlIfGetRequest(servletRequest));
    }
    if ("csv".equalsIgnoreCase(requestParameters.getFormat())) {
        ExecutionUtils exeUtils = new ExecutionUtils(processingData);
        exeUtils.writeCsvResponse(resultSet, servletResponse, ExecutionUtils.createCsvTopComments(URL, TEXT, Application.API_VERSION, metadata));
        return null;
    }
    return new GroupByResponse(new Attribution(URL, TEXT), Application.API_VERSION, metadata, resultSet);
}

