    if (groupByKey.length != 1) {
        throw new BadRequestException(ExceptionMessages.GROUP_BY_KEY_PARAM);
    }
    mapRed = inputProcessor.processParameters();
    ProcessingData processingData = inputProcessor.getProcessingData();
    RequestParameters requestParameters = processingData.getRequestParameters();
    String[] groupByValues = inputProcessor.splitParamOnComma(inputProcessor.createEmptyArrayIfNull(servletRequest.getParameterValues("groupByValues")));
    TagTranslator tt = DbConnData.tagTranslator;
    Integer[] valuesInt = new Integer[groupByValues.length];
    ArrayList<Pair<Integer, Integer>> zeroFill = new ArrayList<>();
    int keyInt = tt.getOSHDBTagKeyOf(groupByKey[0]).map(OSHDBTagKey::toInt).orElse(-2);
    if (groupByValues.length != 0) {
        for (int j = 0; j < groupByValues.length; j++) {
            valuesInt[j] = tt.getOSHDBTagOf(groupByKey[0], groupByValues[j]).map(OSHDBTag::getValue).orElse(-j - 1);
            zeroFill.add(new ImmutablePair<>(keyInt, valuesInt[j]));
        }
    }
    var arrGeoms = new ArrayList<>(processingData.getBoundaryList());
    // intentionally as check for P on Polygonal is already performed
    @SuppressWarnings("unchecked")
    Map<Integer, P> geoms = IntStream.range(0, arrGeoms.size()).boxed().collect(Collectors.toMap(idx -> idx, idx -> (P) arrGeoms.get(idx)));
    MapAggregator<Integer, OSMEntitySnapshot> mapAgg = mapRed.aggregateByGeometry(geoms);
    if (processingData.isContainingSimpleFeatureTypes()) {
        mapAgg = inputProcessor.filterOnSimpleFeatures(mapAgg);
    }
    Optional<FilterExpression> filter = processingData.getFilterExpression();
    if (filter.isPresent()) {
        mapAgg = mapAgg.filter(filter.get());
    }
    var result = ExecutionUtils.computeNestedResult(requestResource, mapAgg.map(f -> ExecutionUtils.mapSnapshotToTags(keyInt, valuesInt, f)).aggregateBy(Pair::getKey, zeroFill).map(Pair::getValue).aggregateByTimestamp(OSMEntitySnapshot::getTimestamp));
    var groupByResult = OSHDBCombinedIndex.nest(result);
    GroupByResult[] resultSet = new GroupByResult[groupByResult.entrySet().size()];
    InputProcessingUtils utils = inputProcessor.getUtils();
    Object[] boundaryIds = utils.getBoundaryIds();
    int count = 0;
    ArrayList<Geometry> boundaries = new ArrayList<>(processingData.getBoundaryList());
    for (var entry : groupByResult.entrySet()) {
        int boundaryIdentifier = entry.getKey().getFirstIndex();
        ElementsResult[] results = ExecutionUtils.fillElementsResult(entry.getValue(), requestParameters.isDensity(), df, boundaries.get(boundaryIdentifier));
        int tagValue = entry.getKey().getSecondIndex().getValue();
        String tagIdentifier;
        // check for non-remainder objects (which do have the defined key and value)
        if (entry.getKey().getSecondIndex().getKey() == -1) {
            tagIdentifier = "remainder";
        } else if (tagValue < 0) {
            tagIdentifier = groupByKey[0] + '=' + groupByValues[-tagValue - 1];
        } else {
            tagIdentifier = tt.lookupTag(keyInt, tagValue).toString();
        }
        resultSet[count] = new GroupByResult(new Object[] { boundaryIds[boundaryIdentifier], tagIdentifier }, results);
        count++;
    }
    // used to remove null objects from the resultSet
    resultSet = Arrays.stream(resultSet).filter(Objects::nonNull).toArray(GroupByResult[]::new);
    Metadata metadata = null;
    if (processingData.isShowMetadata()) {
        long duration = System.currentTimeMillis() - startTime;
        metadata = new Metadata(duration, Description.aggregateGroupByBoundaryGroupByTag(requestParameters.isDensity(), requestResource.getDescription(), requestResource.getUnit()), inputProcessor.getRequestUrlIfGetRequest(servletRequest));
    }
    if ("csv".equalsIgnoreCase(requestParameters.getFormat())) {
        ExecutionUtils exeUtils = new ExecutionUtils(processingData);
        exeUtils.writeCsvResponse(resultSet, servletResponse, ExecutionUtils.createCsvTopComments(URL, TEXT, Application.API_VERSION, metadata));
        return null;
    } else if ("geojson".equalsIgnoreCase(requestParameters.getFormat())) {
        return GroupByResponse.of(new Attribution(URL, TEXT), Application.API_VERSION, metadata, "FeatureCollection", GroupByBoundaryGeoJsonGenerator.createGeoJsonFeatures(resultSet, processingData.getGeoJsonGeoms()));
    }
    return new GroupByResponse(new Attribution(URL, TEXT), Application.API_VERSION, metadata, resultSet);
}

