    List<String> possibleParams = new LinkedList<>(Arrays.asList("bboxes", "bcircles", "bpolys", "types", "keys", "values", "timeout", "time", "showMetadata", "filter"));
    if (uri.contains("/count") || uri.contains("/length") || uri.contains("/area") || uri.contains("/perimeter")) {
