    MapReducer<List<OSMContribution>> mapRedContributions = mapRedContribution.groupByEntity();
    MapReducer<List<OSMEntitySnapshot>> mapRedSnapshots = mapRedSnapshot.groupByEntity();
    Optional<FilterExpression> filter = processingData.getFilterExpression();
    if (filter.isPresent()) {
        mapRedSnapshots = mapRedSnapshots.filter(filter.get());
        mapRedContributions = mapRedContributions.filter(filter.get());
    }
    final boolean isContainingSimpleFeatureTypes = processingData.isContainingSimpleFeatureTypes();
    DataExtractionTransformer dataExtractionTransformer = new DataExtractionTransformer(startTimestamp, endTimestamp, filter.orElse(null), isContributionsEndpoint, isContributionsLatestEndpoint, clipGeometries, includeTags, includeOSMMetadata, includeContributionTypes, utils, exeUtils, keysInt, elementsGeometry, simpleFeatureTypes, isContainingSimpleFeatureTypes);
    MapReducer<Feature> contributionPreResult = mapRedContributions.flatMap(dataExtractionTransformer::buildChangedFeatures).filter(Objects::nonNull);
    Metadata metadata = null;
    if (processingData.isShowMetadata()) {
        metadata = new Metadata(null, requestResource.getDescription(), inputProcessor.getRequestUrlIfGetRequest(servletRequest));
    }
    ExtractionResponse osmData = new ExtractionResponse(ATTRIBUTION, Application.API_VERSION, metadata, "FeatureCollection", Collections.emptyList());
    MapReducer<Feature> snapshotPreResult = null;
    if (!isContributionsEndpoint) {
        // handles cases where valid_from = t_start, valid_to = t_end; i.e. non-modified data
        snapshotPreResult = mapRedSnapshots.filter(snapshots -> snapshots.size() == 2).filter(snapshots -> snapshots.get(0).getGeometry() == snapshots.get(1).getGeometry() && snapshots.get(0).getEntity().getVersion() == snapshots.get(1).getEntity().getVersion()).map(snapshots -> snapshots.get(0)).flatMap(dataExtractionTransformer::buildUnchangedFeatures).filter(Objects::nonNull);
    }
    try (Stream<Feature> snapshotStream = (snapshotPreResult != null) ? snapshotPreResult.stream() : Stream.empty();
        Stream<Feature> contributionStream = contributionPreResult.stream()) {
        exeUtils.streamResponse(servletResponse, osmData, Stream.concat(contributionStream, snapshotStream));
    }
}

