    if (groupByKey.length != 1) {
        throw new BadRequestException(ExceptionMessages.GROUP_BY_KEY_PARAM);
    }
    MapReducer<OSMContribution> mapRed = null;
    mapRed = inputProcessor.processParameters();
    ProcessingData processingData = inputProcessor.getProcessingData();
    RequestParameters requestParameters = processingData.getRequestParameters();
    String[] groupByValues = inputProcessor.splitParamOnComma(inputProcessor.createEmptyArrayIfNull(servletRequest.getParameterValues("groupByValues")));
    TagTranslator tt = DbConnData.tagTranslator;
    Integer[] valuesInt = new Integer[groupByValues.length];
    ArrayList<Pair<Integer, Integer>> zeroFill = new ArrayList<>();
    int keyInt = tt.getOSHDBTagKeyOf(groupByKey[0]).map(OSHDBTagKey::toInt).orElse(-3);
    if (groupByValues.length != 0) {
        for (int j = 0; j < groupByValues.length; j++) {
            valuesInt[j] = tt.getOSHDBTagOf(groupByKey[0], groupByValues[j]).map(OSHDBTag::getValue).orElse(-j - 1);
            zeroFill.add(new ImmutablePair<>(keyInt, valuesInt[j]));
        }
    }
    SortedMap<OSHDBCombinedIndex<OSHDBTimestamp, Pair<Integer, Integer>>, Integer> result = null;
    result = mapRed.filter(ExecutionUtils.contributionsFilter(servletRequest.getParameter(CONTRIBUTION_TYPE_PARAMETER))).flatMap(f -> {
        List<Pair<Pair<Integer, Integer>, OSMContribution>> res = new LinkedList<>();
        Iterable<OSHDBTag> tags = ExecutionUtils.extractContributionTags(f);
        for (OSHDBTag tag : tags) {
            int tagKeyId = tag.getKey();
            int tagValueId = tag.getValue();
            if (tagKeyId == keyInt) {
                if (valuesInt.length == 0) {
                    res.add(new ImmutablePair<>(new ImmutablePair<>(tagKeyId, tagValueId), f));
                }
                for (int value : valuesInt) {
                    if (tagValueId == value) {
                        res.add(new ImmutablePair<>(new ImmutablePair<>(tagKeyId, tagValueId), f));
                    }
                }
            }
        }
        if (res.isEmpty()) {
            res.add(new ImmutablePair<>(new ImmutablePair<>(-1, -1), f));
        }
        res.add(new ImmutablePair<>(new ImmutablePair<>(-2, -2), f));
        return res;
    }).aggregateByTimestamp().aggregateBy(Pair::getKey, zeroFill).map(Pair::getValue).map(OSMContribution::getContributorUserId).countUniq();
    Geometry geom = inputProcessor.getGeometry();
    SortedMap<Pair<Integer, Integer>, SortedMap<OSHDBTimestamp, Integer>> groupByResult;
    groupByResult = ExecutionUtils.nest(result);
    GroupByResult[] resultSet = new GroupByResult[groupByResult.size()];
    String groupByName = "";
    int count = 0;
    for (Entry<Pair<Integer, Integer>, SortedMap<OSHDBTimestamp, Integer>> entry : groupByResult.entrySet()) {
        ContributionsResult[] results = ExecutionUtils.fillContributionsResult(entry.getValue(), requestParameters.isDensity(), inputProcessor, df, geom);
        if (entry.getKey().getKey() == -2) {
            groupByName = "total";
        } else if (entry.getKey().getKey() == -1) {
            groupByName = "remainder";
        } else if (entry.getKey().getValue() < 0) {
            groupByName = groupByKey[0] + '=' + groupByValues[-entry.getKey().getValue() - 1];
        } else {
            groupByName = tt.lookupTag(keyInt, entry.getKey().getValue()).toString();
        }
        resultSet[count] = new GroupByResult(groupByName, results);
        count++;
    }
    Metadata metadata = null;
    if (processingData.isShowMetadata()) {
        long duration = System.currentTimeMillis() - startTime;
        metadata = new Metadata(duration, Description.countUsersGroupByTag(isDensity), inputProcessor.getRequestUrlIfGetRequest(servletRequest));
    }
    if ("csv".equalsIgnoreCase(requestParameters.getFormat())) {
        ExecutionUtils exeUtils = new ExecutionUtils(processingData);
        exeUtils.writeCsvResponse(resultSet, servletResponse, ExecutionUtils.createCsvTopComments(URL, TEXT, Application.API_VERSION, metadata));
        return null;
    }
    return new GroupByResponse(new Attribution(URL, TEXT), Application.API_VERSION, metadata, resultSet);
}

