    switch(requestResource) {
        case COUNT:
            result = mapRed.aggregateByTimestamp().count();
            break;
        case PERIMETER:
            result = mapRedGeom.aggregateByTimestamp().sum(geom -> {
                if (!(geom instanceof Polygonal)) {
                    return 0.0;
                }
                return ExecutionUtils.cacheInUserData(geom, () -> Geo.lengthOf(geom.getBoundary()));
            });
            break;
        case LENGTH:
            result = mapRedGeom.aggregateByTimestamp().sum(geom -> ExecutionUtils.cacheInUserData(geom, () -> Geo.lengthOf(geom)));
            break;
        case AREA:
            result = mapRedGeom.aggregateByTimestamp().sum(geom -> ExecutionUtils.cacheInUserData(geom, () -> Geo.areaOf(geom)));
            break;
        default:
            throw new RuntimeException("Unsupported RequestResource type for this processing. " + "Only COUNT, LENGTH, PERIMETER, and AREA are permitted here");
