computeCountLengthPerimeterAreaGbB(Reque.code:
{
    if (boundaryType == BoundaryType.NOBOUNDARY) {
        throw new BadRequestException(ExceptionMessages.NO_BOUNDARY);
    }
    ArrayList<Geometry> arrGeoms = new ArrayList<>(processingData.getBoundaryList());
    // intentionally as check for P on Polygonal is already performed
    @SuppressWarnings("unchecked")
    Map<Integer, P> geoms = IntStream.range(0, arrGeoms.size()).boxed().collect(Collectors.toMap(idx -> idx, idx -> (P) arrGeoms.get(idx)));
    MapAggregator<OSHDBCombinedIndex<OSHDBTimestamp, Integer>, OSMEntitySnapshot> mapAgg = mapRed.aggregateByTimestamp().aggregateByGeometry(geoms);
    if (processingData.isContainingSimpleFeatureTypes()) {
        mapAgg = inputProcessor.filterOnSimpleFeatures(mapAgg);
    }
    Optional<FilterExpression> filter = processingData.getFilterExpression();
    if (filter.isPresent()) {
        mapAgg = mapAgg.filter(filter.get());
    }
    var mapAggGeom = mapAgg.map(OSMEntitySnapshot::getGeometry);
    switch(requestResource) {
        case COUNT:
            return mapAgg.count();
        case PERIMETER:
            return mapAggGeom.sum(geom -> {
                if (!(geom instanceof Polygonal)) {
                    return 0.0;
                }
                return ExecutionUtils.cacheInUserData(geom, () -> Geo.lengthOf(geom.getBoundary()));
            });
        case LENGTH:
            return mapAggGeom.sum(geom -> ExecutionUtils.cacheInUserData(geom, () -> Geo.lengthOf(geom)));
        case AREA:
            return mapAggGeom.sum(geom -> ExecutionUtils.cacheInUserData(geom, () -> Geo.areaOf(geom)));
        default:
            return null;
    }
}

aggregateGroupByBoundary().code:
{
    processingData.setGroupByBoundary(true);
    RequestParameters requestParameters = processingData.getRequestParameters();
    MapReducer<OSMEntitySnapshot> mapRed = inputProcessor.processParameters();
    InputProcessingUtils utils = inputProcessor.getUtils();
    var result = computeCountLengthPerimeterAreaGbB(requestResource, processingData.getBoundaryType(), mapRed, inputProcessor);
    SortedMap<Integer, ? extends SortedMap<OSHDBTimestamp, ? extends Number>> groupByResult;
    groupByResult = ExecutionUtils.nest(result);
    GroupByResult[] resultSet = new GroupByResult[groupByResult.size()];
    Object groupByName;
    Object[] boundaryIds = utils.getBoundaryIds();
    int count = 0;
    ArrayList<Geometry> boundaries = new ArrayList<>(processingData.getBoundaryList());
    for (Entry<Integer, ? extends SortedMap<OSHDBTimestamp, ? extends Number>> entry : groupByResult.entrySet()) {
        ElementsResult[] results = fillElementsResult(entry.getValue(), requestParameters.isDensity(), df, boundaries.get(count));
        groupByName = boundaryIds[count];
        resultSet[count] = new GroupByResult(groupByName, results);
        count++;
    }
    String description = Description.aggregate(requestParameters.isDensity(), requestResource.getDescription(), requestResource.getUnit());
    Metadata metadata = generateMetadata(description);
    if ("geojson".equalsIgnoreCase(requestParameters.getFormat())) {
        return GroupByResponse.of(ATTRIBUTION, Application.API_VERSION, metadata, "FeatureCollection", createGeoJsonFeatures(resultSet, processingData.getGeoJsonGeoms()));
    } else if ("csv".equalsIgnoreCase(requestParameters.getFormat())) {
        return writeCsv(createCsvTopComments(metadata), writeCsvResponse(resultSet));
    }
    return new GroupByResponse(ATTRIBUTION, Application.API_VERSION, metadata, resultSet);
}

