    String bpolys = createEmptyStringIfNull(processingData.getRequestParameters().getBpolys());
    String[] types = splitParamOnComma(createEmptyArrayIfNull(processingData.getRequestParameters().getTypes()));
    String[] keys = splitParamOnComma(createEmptyArrayIfNull(processingData.getRequestParameters().getKeys()));
    String[] values = splitParamOnComma(createEmptyArrayIfNull(processingData.getRequestParameters().getValues()));
    String[] time = splitParamOnComma(createEmptyArrayIfNull(processingData.getRequestParameters().getTime()));
