        String firstElem = timeData[0];
        timeData = ArrayUtils.remove(timeData, 0);
        mapRed = mapRed.timestamps(firstElem, firstElem, timeData);
    }
    utils.setToTimestamps(toTimestamps);
    return mapRed;
