    Metadata metadata = null;
    if (processingData.isShowMetadata()) {
        long duration = System.currentTimeMillis() - startTime;
        String description;
        if (isUsersRequest) {
            description = Description.countUsersGroupByBoundary(requestParameters.isDensity());
        } else {
            description = Description.countContributionsGroupByBoundary(requestParameters.isDensity());
        }
        metadata = new Metadata(duration, description, inputProcessor.getRequestUrlIfGetRequest(servletRequest));
    }
    if ("geojson".equalsIgnoreCase(requestParameters.getFormat())) {
        return GroupByResponse.of(new Attribution(URL, TEXT), Application.API_VERSION, metadata, "FeatureCollection", GroupByBoundaryGeoJsonGenerator.createGeoJsonFeatures(resultSet, processingData.getGeoJsonGeoms()));
