extract().code:
{
    inputProcessor.getProcessingData().setFullHistory(true);
    InputProcessor snapshotInputProcessor = new InputProcessor(servletRequest, true, false);
    snapshotInputProcessor.getProcessingData().setFullHistory(true);
    MapReducer<OSMEntitySnapshot> mapRedSnapshot = null;
    MapReducer<OSMContribution> mapRedContribution = null;
    if (DbConnData.db instanceof OSHDBIgnite) {
        // on ignite: Use AffinityCall backend, which is the only one properly supporting streaming
        // of result data, without buffering the whole result in memory before returning the result.
        // This allows to write data out to the client via a chunked HTTP response.
        mapRedSnapshot = snapshotInputProcessor.processParameters(ComputeMode.AFFINITY_CALL);
        mapRedContribution = inputProcessor.processParameters(ComputeMode.AFFINITY_CALL);
    } else {
        mapRedSnapshot = snapshotInputProcessor.processParameters();
        mapRedContribution = inputProcessor.processParameters();
    }
    RequestParameters requestParameters = processingData.getRequestParameters();
    String[] time = inputProcessor.splitParamOnComma(inputProcessor.createEmptyArrayIfNull(servletRequest.getParameterValues("time")));
    if (time.length != 2) {
        throw new BadRequestException(ExceptionMessages.TIME_FORMAT_CONTRS_EXTRACTION_AND_FULL_HISTORY);
    }
    TagTranslator tt = DbConnData.tagTranslator;
    String[] keys = requestParameters.getKeys();
    final Set<Integer> keysInt = ExecutionUtils.keysToKeysInt(keys, tt);
    final ExecutionUtils exeUtils = new ExecutionUtils(processingData);
    inputProcessor.processPropertiesParam();
    inputProcessor.processIsUnclippedParam();
    InputProcessingUtils utils = inputProcessor.getUtils();
    final boolean includeTags = inputProcessor.includeTags();
    final boolean includeOSMMetadata = inputProcessor.includeOSMMetadata();
    final boolean includeContributionTypes = inputProcessor.includeContributionTypes();
    final boolean clipGeometries = inputProcessor.isClipGeometry();
    final boolean isContributionsLatestEndpoint = requestResource.equals(RequestResource.CONTRIBUTIONSLATEST);
    final boolean isContributionsEndpoint = isContributionsLatestEndpoint || requestResource.equals(RequestResource.CONTRIBUTIONS);
    final Set<SimpleFeatureType> simpleFeatureTypes = processingData.getSimpleFeatureTypes();
    String startTimestamp = IsoDateTimeParser.parseIsoDateTime(requestParameters.getTime()[0]).format(DateTimeFormatter.ISO_DATE_TIME);
    String endTimestamp = IsoDateTimeParser.parseIsoDateTime(requestParameters.getTime()[1]).format(DateTimeFormatter.ISO_DATE_TIME);
    MapReducer<List<OSMContribution>> mapRedContributions = mapRedContribution.groupByEntity();
    MapReducer<List<OSMEntitySnapshot>> mapRedSnapshots = mapRedSnapshot.groupByEntity();
    Optional<FilterExpression> filter = processingData.getFilterExpression();
    if (filter.isPresent()) {
        mapRedSnapshots = mapRedSnapshots.filter(filter.get());
        mapRedContributions = mapRedContributions.filter(filter.get());
    }
    final boolean isContainingSimpleFeatureTypes = processingData.isContainingSimpleFeatureTypes();
    DataExtractionTransformer dataExtractionTransformer = new DataExtractionTransformer(startTimestamp, endTimestamp, filter.orElse(null), isContributionsEndpoint, isContributionsLatestEndpoint, clipGeometries, includeTags, includeOSMMetadata, includeContributionTypes, utils, exeUtils, keysInt, elementsGeometry, simpleFeatureTypes, isContainingSimpleFeatureTypes);
    MapReducer<Feature> contributionPreResult = mapRedContributions.flatMap(dataExtractionTransformer::buildChangedFeatures).filter(Objects::nonNull);
    Metadata metadata = null;
    if (processingData.isShowMetadata()) {
        metadata = new Metadata(null, requestResource.getDescription(), inputProcessor.getRequestUrlIfGetRequest(servletRequest));
    }
    ExtractionResponse osmData = new ExtractionResponse(ATTRIBUTION, Application.API_VERSION, metadata, "FeatureCollection", Collections.emptyList());
    MapReducer<Feature> snapshotPreResult = null;
    if (!isContributionsEndpoint) {
        // handles cases where valid_from = t_start, valid_to = t_end; i.e. non-modified data
        snapshotPreResult = mapRedSnapshots.filter(snapshots -> snapshots.size() == 2).filter(snapshots -> snapshots.get(0).getGeometry() == snapshots.get(1).getGeometry() && snapshots.get(0).getEntity().getVersion() == snapshots.get(1).getEntity().getVersion()).map(snapshots -> snapshots.get(0)).flatMap(dataExtractionTransformer::buildUnchangedFeatures).filter(Objects::nonNull);
    }
    try (Stream<Feature> snapshotStream = (snapshotPreResult != null) ? snapshotPreResult.stream() : Stream.empty();
        Stream<Feature> contributionStream = contributionPreResult.stream()) {
        exeUtils.streamResponse(servletResponse, osmData, Stream.concat(contributionStream, snapshotStream));
    }
}

